-- programme_purpose (ISO-5667-1-01)
update public.fields set verification_status='verified_against_standard', verification_quote='Esta norma establece los principios generales que se deben aplicar en el diseño de programas de muestreo para los propósitos del control de calidad, la caracterización de la calidad, y la identificación de las fuentes de contaminación del agua, incluyendo los sedimentos y los lodos. — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§1, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='7724c1c4-2242-4a64-89e9-105f141249c0' and verification_status not in ('verified_against_standard','corrected');
-- matrix_type (ISO-5667-1-01)
update public.fields set verification_status='verified_against_standard', verification_quote='Siempre que se deba caracterizar un volumen de agua, sedimentos o lodos, suele ser imposible examinar todo el sistema y entonces es necesario tomar muestras. Las muestras recolectadas deben ser representativas del sistema por caracterizar — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§1, §3, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='f12dc5d6-5551-4f3c-837f-7837268e908f' and verification_status not in ('verified_against_standard','corrected');
-- normative_references_consulted (ISO-5667-1-01)
update public.fields set verification_status='verified_against_standard', verification_quote='Las siguientes normas contienen disposiciones que, mediante la referencia dentro de este texto, constituyen la integridad del mismo. En el momento de su publicación eran válidas las ediciones indicadas. Todas las normas están sujetas a actualización; los participantes, mediante acuerdos basados en esta norma, deben investigar la posibilidad de aplicar la última versión de las normas mencionadas a continuación. — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§2, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='e7a3adcc-3931-43a4-84c6-df016b6e387f' and verification_status not in ('verified_against_standard','corrected');
-- objectives_defined (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Antes de diseñar cualquier programa de muestreo es muy importante establecer los objetivos, puesto que son los factores principales al determinar la posición de los sitios de muestreo, la frecuencia, la duración, los procedimientos del muestreo, el tratamiento posterior de las muestras, y los requisitos analíticos. — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§3, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='c38ba183-3f7a-422a-9fd7-c417237f0ecc' and verification_status not in ('verified_against_standard','corrected');
-- preliminary_survey_done (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Es necesario efectuar una visita previa para verificar los puntos de muestreo, recopilar información preliminar e información secundaria, definir los procedimientos y efectuar el muestreo preliminar y un programa de análisis antes de que se definan los objetivos finales. — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§3, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='6bf5e8c4-b0d7-4a76-b92f-f0abf0a6416e' and verification_status not in ('verified_against_standard','corrected');
-- prior_data_reviewed (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Es importante tener en cuenta todos los datos pertinentes procedentes de los programas anteriores en localizaciones iguales o semejantes y cualquier otra información sobre las condiciones locales. También puede ser valiosa la experiencia personal anterior. — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§3, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='6bf32e7e-862b-4267-990e-c804033058a4' and verification_status not in ('verified_against_standard','corrected');
-- parameter_list (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Adicionalmente, se debe compilar una lista de parámetros de interés y se deben consultar los procedimientos analíticos pertinentes, pues éstos generalmente darán orientación acerca de las precauciones que se han de observar durante el muestreo y el manejo posterior. — printed p.1 / PDF p.2', verification_note='VA-verified 2026-09-08 (§3, printed p.1 / PDF p.2) [VA]', verified_at=now() where id='4a2d2a4b-044d-4122-8535-5793d9b09e5d' and verification_status not in ('verified_against_standard','corrected');
-- requirement_class (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Establecer el orden de los niveles de concentración o las cargas de los parámetros específicos en posiciones seleccionadas (por ejemplo en la superficie de un cuerpo de agua o dentro de ésta) o, con sedimentos, para obtener una indicación visual de su naturaleza. | Establecer en detalle los niveles de concentración o las distribuciones de las cargas de parámetros físicos o químicos y de especies biológicas de interés en todo cuerpo de agua o en parte de la misma. — printed p.2 / PDF p.3', verification_note='VA-verified 2026-09-08 (§4.1 y §4.2, printed p.2 / PDF p.3) [VA]', verified_at=now() where id='30af289e-c335-472a-80c1-189392080286' and verification_status not in ('verified_against_standard','corrected');
-- specific_objective (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Estas razones para el muestreo se pueden subdividir adicionalmente en objetivos más específicos, tales como los siguientes: | Determinar la conveniencia del agua para un uso propuesto y, si es necesario, evaluar cualquier requisito de tratamiento o de control — printed p.2 / PDF p.3', verification_note='VA-verified 2026-09-08 (§4.2 a)-r), printed p.2 / PDF p.3) [VA]', verified_at=now() where id='fef789e1-ee09-40d3-983b-1c6bd0ac4984' and verification_status not in ('verified_against_standard','corrected');
-- variability_profile (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Los programas de muestreo pueden ser complejos en situaciones en las cuales ocurren variaciones amplias y rápidas en las concentraciones de los factores determinantes que interesan. | Inclusive cuando los cambios en la concentración son lentos y no muy marcados, la evaluación de un área grande de desagüe, tal como una cuenca de río, es un ejercicio complejo. — printed p.3 / PDF p.4', verification_note='VA-verified 2026-09-08 (§5.1, §5.2, printed p.3 / PDF p.4) [VA]', verified_at=now() where id='6dccafd3-f475-4092-9fd4-f3200cb01637' and verification_status not in ('verified_against_standard','corrected');
-- boundary_sampling_avoided (ISO-5667-1-02)
update public.fields set verification_status='verified_against_standard', verification_quote='Se debe evitar el muestreo en las fronteras de los sistemas o cerca de éstas, salvo que las condiciones sean de interés especial. — printed p.3 / PDF p.4', verification_note='VA-verified 2026-09-08 (§5.1, printed p.3 / PDF p.4) [VA]', verified_at=now() where id='b93e6ca4-42d0-4f8a-a9b7-8925f0216d73' and verification_status not in ('verified_against_standard','corrected');
-- safety_regulations_considered (ISO-5667-1-03)
update public.fields set verification_status='verified_against_standard', verification_quote='El personal responsable de diseñar programas de muestreo y de efectuar operaciones de muestreo debe asegurarse de que se tengan en cuenta los requisitos de las regulaciones de seguridad pertinentes y de que el personal de muestreo esté informado de las precauciones necesarias que se deben tener en dichas operaciones. — printed p.3 / PDF p.4', verification_note='VA-verified 2026-09-08 (§7.1, printed p.3 / PDF p.4) [VA]', verified_at=now() where id='2e0f245e-d435-4c53-a0d1-9d4ceb73345b' and verification_status not in ('verified_against_standard','corrected');
-- life_jackets_lines_used (ISO-5667-1-03)
update public.fields set verification_status='verified_against_standard', verification_quote='Para garantizar la seguridad del personal y del equipo, se deben considerar las condiciones climáticas. Al tomar muestras en grandes masas de agua se deben usar chaquetas salvavidas y cuerdas salvavidas. — printed p.3 / PDF p.4', verification_note='VA-verified 2026-09-08 (§7.2, printed p.3 / PDF p.4) [VA]', verified_at=now() where id='10ac43b4-e7a3-4eea-9b0a-13e6a8b242c6' and verification_status not in ('verified_against_standard','corrected');
-- hazardous_atmosphere_tested (ISO-5667-1-03)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando el personal tenga que entrar en atmósferas peligrosas, debe disponer de equipo de protección contra gases, aparatos de respiración, aparatos de resucitación y demás equipo de seguridad adecuado a las circunstancias. Además, antes de que el personal entre en espacios cerrados, se debe medir la concentración de oxígeno y de cualquier vapor o gas tóxico que pueda estar presente. — printed p.4 / PDF p.5', verification_note='VA-verified 2026-09-08 (§7.8, printed p.4 / PDF p.5) [VA]', verified_at=now() where id='bdd960ac-3ffb-4d60-a0e3-e23447af789e' and verification_status not in ('verified_against_standard','corrected');
-- electrical_hazard_minimized (ISO-5667-1-03)
update public.fields set verification_status='verified_against_standard', verification_quote='El uso de equipo de muestreo operado eléctricamente en el agua o cerca de ella puede presentar peligros especiales de electrocución. Se deben planificar los procedimientos de trabajo, el diseño del sitio y el mantenimiento del equipo, de tal forma que se minimicen los riesgos. — printed p.4 / PDF p.5', verification_note='VA-verified 2026-09-08 (§7.11, printed p.4 / PDF p.5) [VA]', verified_at=now() where id='140725fb-18af-478a-8b18-06c9ed1798e9' and verification_status not in ('verified_against_standard','corrected');
-- network_design (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='Dependiendo de los objetivos por alcanzar (véase el numeral 6), la red de muestreo puede tener cualquier forma desde un solo sitio hasta todo un desagüe de río. Una red básica de río puede comprender sitios de muestreo en el límite de la marea, tributarios principales en su confluencia, y descargas principales de afluentes de aguas residuales o industriales. — printed p.4 / PDF p.5', verification_note='VA-verified 2026-09-08 (§8.1, printed p.4 / PDF p.5) [VA]', verified_at=now() where id='d1143703-3dcd-4ea8-a7e0-287d246308e3' and verification_status not in ('verified_against_standard','corrected');
-- sampling_location_identified (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='La identificación de la localización del muestreo permite tomar muestras comparativas en otros momentos. | Para el muestreo desde un bote en estas situaciones, se deben utilizar métodos instrumentales para la identificación de la localización. Las referencias de mapas u otras formas estándar de referencia pueden ser muy valiosas. — printed p.4 / PDF p.5', verification_note='VA-verified 2026-09-08 (§8.2, printed p.4 / PDF p.5) [VA]', verified_at=now() where id='7d10b346-d88b-45ab-a1a2-86d03eeb3fba' and verification_status not in ('verified_against_standard','corrected');
-- flow_character (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='Idealmente, las muestras se deben tomar en líquidos turbulentos, bien mezclados; si se trata de flujos por conductos, siempre que sea posible, se debe inducir la turbulencia. | El flujo puede cambiar de paso por conducto a corriente turbulenta y viceversa. — printed p.4 / PDF p.5', verification_note='VA-verified 2026-09-08 (§8.3, §8.4, printed p.4 / PDF p.5) [VA]', verified_at=now() where id='71e8af1f-fc0a-474a-afb5-f65a8e04288f' and verification_status not in ('verified_against_standard','corrected');
-- pipe_nominal_bore (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='Los líquidos se deben bombear a través de tubos de tamaño adecuado (por ejemplo, al muestrear líquidos heterogéneos, de conducto nominal mínimo de 25 mm) a velocidades lineales suficientemente altas para mantener las características de flujo turbulento. Se deben evitar los recorridos de tubo horizontal. — printed p.4 / PDF p.5', verification_note='VA-verified 2026-09-08 (§8.6, printed p.4 / PDF p.5) [VA]', verified_at=now() where id='a378d740-3ada-451d-8b88-0763cd3ec47b' and verification_status not in ('verified_against_standard','corrected');
-- isokinetic_sampling (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='Idealmente, la velocidad lineal debe ser suficiente para inducir la turbulencia, y las muestras se deben tomar en condiciones isocinéticas (véase la NTC 3650-2 (ISO 6107/2)). Si esto no es posible, se debe tomar una muestra a través de una sección transversal completa del flujo. — printed p.5 / PDF p.6', verification_note='VA-verified 2026-09-08 (§8.9, printed p.5 / PDF p.6) [VA]', verified_at=now() where id='e4d9335e-517a-4a95-9c99-307085ed21af' and verification_status not in ('verified_against_standard','corrected');
-- volatiles_minimal_suction (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='El material del cual se deban tomar muestras debe ser bombeado con mínima fuerza de succión. Toda la tubería se debe mantener llena y la muestra se debe extraer de un tubo presurizado después de dejar que el material fluya y se deseche un poco, para garantizar que la muestra recogida sea representativa. — printed p.5 / PDF p.6', verification_note='VA-verified 2026-09-08 (§8.10, printed p.5 / PDF p.6) [VA]', verified_at=now() where id='31905ec3-40d1-4e8d-b5eb-8c67fe753655' and verification_status not in ('verified_against_standard','corrected');
-- weather_recorded (ISO-5667-1-04)
update public.fields set verification_status='verified_against_standard', verification_quote='Los cambios en las condiciones meteorológicas pueden inducir variaciones marcadas en la calidad del agua; tales cambios se deben registrar y se deben tener en cuenta al interpretar los resultados. — printed p.5 / PDF p.6', verification_note='VA-verified 2026-09-08 (§8.13, printed p.5 / PDF p.6) [VA]', verified_at=now() where id='6f21cb89-2733-4b8d-902a-b6bd0d0dadc1' and verification_status not in ('verified_against_standard','corrected');
-- water_situation_type (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='En esta sección se tratan las diversas situaciones que se pueden encontrar en la práctica del muestreo y el grado en que estas situaciones inciden en la selección de un sitio de muestreo. — printed p.3 / PDF p.4', verification_note='VA-verified 2026-09-08 (§6, §9-§13, printed p.3 / PDF p.4) [VA]', verified_at=now() where id='5c1227a6-70ae-4fe5-85a9-9ea78eabc7ca' and verification_status not in ('verified_against_standard','corrected');
-- groundwater_purged (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando se efectúa muestreo para evaluar la calidad del agua contenida en un depósito acuífero, el pozo debe bombearse antes de efectuar el muestreo para así asegurarse de que se extrae agua nueva del depósito. | Los pozos cercanos a materiales susceptibles de corrosión, siempre deben bombearse completamente antes del muestreo, para así tener seguridad de que se eliminen del sistema todos los productos de corrosión acumulados. — printed p.6 / PDF p.7', verification_note='VA-verified 2026-09-08 (§9.6.2, printed p.6 / PDF p.7) [VA]', verified_at=now() where id='5859b2fd-f803-4b26-90fe-cd9ce2836b74' and verification_status not in ('verified_against_standard','corrected');
-- sampling_depth (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Siempre se debe registrar la profundidad por debajo del nivel del suelo a la cual se toma la muestra. | En los casos en que se requieran muestras representativas de profundidades predeterminadas en el depósito acuífero, se deben utilizar tubos de muestreo para cada profundidad del agujero perforado, o agujeros separados para cada profundidad. — printed p.6 / PDF p.7', verification_note='VA-verified 2026-09-08 (§9.6.2, printed p.6 / PDF p.7) [VA]', verified_at=now() where id='b147ad8a-2ccc-4c2c-ab1b-80a2d978e3fc' and verification_status not in ('verified_against_standard','corrected');
-- upstream_downstream_sampling (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Si el propósito del muestreo es controlar los efectos de una descarga, se debe efectuar muestreo río arriba y río abajo, pero se debe considerar con cuidado la mezcla del agua de descarga y de recibo y sus efectos sobre las muestras río abajo. El muestreo se debe extender por una distancia apropiada río abajo para evaluar los efectos sobre el río. — printed p.6 / PDF p.7', verification_note='VA-verified 2026-09-08 (§9.3.2, printed p.6 / PDF p.7) [VA]', verified_at=now() where id='a725d48f-97a3-459a-8783-95568ffd8cc0' and verification_status not in ('verified_against_standard','corrected');
-- cooling_system_type (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Hay tres tipos principales de sistema de enfriamiento: a) Evaporación abierta. b) Un solo paso (de libre paso). c) Circuito cerrado. — printed p.8 / PDF p.9', verification_note='VA-verified 2026-09-08 (§10.2.4, printed p.8 / PDF p.9) [VA]', verified_at=now() where id='a492fed6-eff8-4e5e-b97a-5a73d44c3dca' and verification_status not in ('verified_against_standard','corrected');
-- manhole_sampled_without_entry (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Con muestreo de cajas compactas de inspección (manhole), por razones de seguridad es preferible que dicha caja de inspección se diseñe de tal modo que se pueda efectuar el muestreo sin entrar. — printed p.9 / PDF p.10', verification_note='VA-verified 2026-09-08 (§11.1, printed p.9 / PDF p.10) [VA]', verified_at=now() where id='08fd0d81-54e2-4724-87e9-461d29f92568' and verification_status not in ('verified_against_standard','corrected');
-- sludge_pipe_diameter (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Si el muestreo va a ser de una tubería, el conducto del muestreo debe tener al menos 50 mm de diámetro para así garantizar que la ocurrencia de bloqueos sea mínima, y las muestras se deben tomar a intervalos de tiempo frecuentes. — printed p.9 / PDF p.10', verification_note='VA-verified 2026-09-08 (§12.1.2, printed p.9 / PDF p.10) [VA]', verified_at=now() where id='f1598372-baf3-46bf-ba8a-0ffcec16df24' and verification_status not in ('verified_against_standard','corrected');
-- composite_multipoint_sample (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='En muchos casos será necesario tomar dos o tres muestras de rutina en puntos diferentes y mezclar éstos para dar una muestra compuesta. — printed p.9 / PDF p.10', verification_note='VA-verified 2026-09-08 (§12.1.1, printed p.9 / PDF p.10) [VA]', verified_at=now() where id='61bc94ff-a44d-47a5-a7b8-d9f6b4b33024' and verification_status not in ('verified_against_standard','corrected');
-- automatic_sampler_protection (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Sin embargo, en los casos en que se usen muestreadores automáticos, éstos se puede situar más arriba de los procesos preliminares, siempre que en la entrada del muestreador se agregue un tamiz o un pequeño macerador con el fin de evitar los bloqueos. — printed p.9 / PDF p.10', verification_note='VA-verified 2026-09-08 (§12.1.1, printed p.9 / PDF p.10) [VA]', verified_at=now() where id='b8f1cbeb-120b-4e3e-b459-59f0b45a44d1' and verification_status not in ('verified_against_standard','corrected');
-- flow_proportional_sampling (ISO-5667-1-05)
update public.fields set verification_status='verified_against_standard', verification_quote='Los dispositivos automáticos de muestreo que recogen muestras a intervalos regulares y que comienzan a un flujo prescrito, ofrecen muchas ventajas. Este equipo se debe instalar en un estado permanente de alistamiento. En muchos casos será deseable el muestreo proporcional al flujo. — printed p.10 / PDF p.11', verification_note='VA-verified 2026-09-08 (§13, printed p.10 / PDF p.11) [VA]', verified_at=now() where id='44395743-9cd9-4826-a417-0e05d3fa4d76' and verification_status not in ('verified_against_standard','corrected');
-- programme_type (ISO-5667-1-06)
update public.fields set verification_status='verified_against_standard', verification_quote='Existen tres tipos principales de programa. Estos se pueden describir como control de calidad, caracterización de la calidad, e identificación de las fuentes de contaminación (véase el numeral 3). Las mediciones hechas para propósitos de control de calidad se pueden usar para la caracterización de la calidad y viceversa. — printed p.10 / PDF p.11', verification_note='VA-verified 2026-09-08 (§15, printed p.10 / PDF p.11) [VA]', verified_at=now() where id='c68f7e2a-3b50-4281-81a3-83e21f8d5d77' and verification_status not in ('verified_against_standard','corrected');
-- control_limits (ISO-5667-1-06)
update public.fields set verification_status='verified_against_standard', verification_quote='Estos programas generalmente involucran el control de la concentración de uno o más factores determinantes dentro de límites definidos. Los resultados se requieren con el fin de decidir si se necesita acción inmediata. Por lo tanto, la frecuencia del muestreo se debe elegir de tal modo que haya más de una probabilidad aceptable de desviaciones importantes fuera de los límites de control, que ocurran entre mediciones sucesivas. — printed p.10 / PDF p.11', verification_note='VA-verified 2026-09-08 (§15.1, printed p.10 / PDF p.11) [VA]', verified_at=now() where id='2e37968a-d888-4348-abc8-4b14ad146f90' and verification_status not in ('verified_against_standard','corrected');
-- target_statistic (ISO-5667-1-06)
update public.fields set verification_status='verified_against_standard', verification_quote='Estos programas se proponen estimar uno o más parámetros estadísticos que caractericen la concentración o su variabilidad, o ambos, durante un período definido. Por ejemplo, la media aritmética o la mediana indican la tendencia central de los resultados, y la desviación estándar indica la variabilidad. — printed p.10 / PDF p.11', verification_note='VA-verified 2026-09-08 (§15.2, printed p.10 / PDF p.11) [VA]', verified_at=now() where id='c6ca0cc7-9395-4a9e-be4d-5f39324954f1' and verification_status not in ('verified_against_standard','corrected');
-- abnormal_frequency_increase (ISO-5667-1-06)
update public.fields set verification_status='verified_against_standard', verification_quote='Es posible que se necesite incrementar la frecuencia del muestreo mientras persistan condiciones anormales, por ejemplo durante la puesta en marcha de una planta por procesos, durante las condiciones de inundación en un río, o en tiempos de florecimiento de algas. — printed p.12 / PDF p.13', verification_note='VA-verified 2026-09-08 (§17, printed p.12 / PDF p.13) [VA]', verified_at=now() where id='2600e7e4-9e37-47c6-89e7-fb8f4c1518da' and verification_status not in ('verified_against_standard','corrected');
-- composite_sample_duration (ISO-5667-1-06)
update public.fields set verification_status='verified_against_standard', verification_quote='Si sólo interesa la calidad promedio durante un período, y siempre que el factor determinante sea estable, puede ser útil que la duración de la recolección de las muestras sea larga y, preferiblemente, igual al período que interesa. Este principio es similar al de la elaboración de muestras compuestas. — printed p.12 / PDF p.13', verification_note='VA-verified 2026-09-08 (§18, printed p.12 / PDF p.13) [VA]', verified_at=now() where id='c5515a42-d22f-4d89-ac80-5f242e3ef673' and verification_status not in ('verified_against_standard','corrected');
-- x_i (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='las estimaciones de la media aritmética verdadera X y la desviación estándar, σ, son la media aritmética, X , y s respectivamente de acuerdo con la siguiente fórmula | Donde xi representa los valores individuales. — printed p.11 / PDF p.12', verification_note='VA-verified 2026-09-08 (§16.4, printed p.11 / PDF p.12) [VA]', verified_at=now() where id='bd3aec17-f34a-42be-8c31-c45971377c21' and verification_status not in ('verified_against_standard','corrected');
-- x_mean (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='Para cierto número de resultados n, tomados al azar, las estimaciones de la media aritmética verdadera X y la desviación estándar, σ, son la media aritmética, X , y s respectivamente de acuerdo con la siguiente fórmula — printed p.11 / PDF p.12', verification_note='VA-verified 2026-09-08 (§16.4, printed p.11 / PDF p.12) [VA]', verified_at=now() where id='4462894b-4ee4-4b4e-8151-ec3815b6ee31' and verification_status not in ('verified_against_standard','corrected');
-- n (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='Para estimar la media aritmética X para un intervalo de confianza dado L en el nivel de confianza seleccionado, el número de muestras necesarias es (2Kσ/L)2. Esto es estrictamente cierto únicamente cuando se conoce σ. — printed p.12 / PDF p.13', verification_note='VA-verified 2026-09-08 (§16.4, printed p.12 / PDF p.13) [VA]', verified_at=now() where id='8e17b978-a178-4fa9-a55e-cd4bdc54ffbd' and verification_status not in ('verified_against_standard','corrected');
-- s (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='Cuando n es grande (véase el numeral 16.1), s difiere poco del valor verdadero σ | Cuando únicamente se dispone de una s estimada, se requerirán más muestras, aunque esto afectará muy poco al valor de K, si s se basa en un número relativamente grande de muestras. — printed p.11-12 / PDF p.12-13', verification_note='VA-verified 2026-09-08 (§16.4, printed p.11-12 / PDF p.12-13) [VA]', verified_at=now() where id='dd00f03e-8c98-4aa8-b00e-83b3211fd60d' and verification_status not in ('verified_against_standard','corrected');
-- sigma (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='Donde σ es la desviación estándar de la distribución. | Esto es estrictamente cierto únicamente cuando se conoce σ. Cuando únicamente se dispone de una s estimada, se requerirán más muestras — printed p.12 / PDF p.13', verification_note='VA-verified 2026-09-08 (§16.4, §16.5, printed p.12 / PDF p.13) [VA]', verified_at=now() where id='34719e36-a501-472b-9147-0d61f2a36232' and verification_status not in ('verified_against_standard','corrected');
-- K (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='donde K tiene el valor dado en la siguiente tabla, dependiendo del nivel de confianza adoptado. | Nivel de confianza 99 98 95 90 80 68 50 | K 2,58 2,33 1,96 1,64 1,28 1,00 0,67 — printed p.11 / PDF p.12', verification_note='VA-verified 2026-09-08 (§16.4, printed p.11 / PDF p.12) [VA]', verified_at=now() where id='85996c78-5550-40e3-a8cb-a1fb033c9a17' and verification_status not in ('verified_against_standard','corrected');
-- confidence_level (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='El nivel de confianza es la probabilidad de que la media aritmética verdadera esté incluida dentro del intervalo de confianza L calculado. | Nivel de confianza 99 98 95 90 80 68 50 | K 2,58 2,33 1,96 1,64 1,28 1,00 0,67 — printed p.11 / PDF p.12', verification_note='VA-verified 2026-09-08 (§16.3, §16.4, printed p.11 / PDF p.12) [VA]', verified_at=now() where id='91abb053-3ca3-4a3a-a6ad-8913247a6450' and verification_status not in ('verified_against_standard','corrected');
-- L (ISO-5667-1-07)
update public.fields set verification_status='verified_against_standard', verification_quote='En la práctica, el intervalo de confianza L de la media aritmética de n resultados, define el intervalo en el cual se encuentra la media aritmética verdadera a un nivel de confianza dado. — printed p.11 / PDF p.12', verification_note='VA-verified 2026-09-08 (§16.2, printed p.11 / PDF p.12) [VA]', verified_at=now() where id='79095d10-a410-4520-b1fc-b4abd91142d2' and verification_status not in ('verified_against_standard','corrected');
-- flow_aspect (ISO-5667-1-08)
update public.fields set verification_status='verified_against_standard', verification_quote='Hay tres aspectos del flujo que es necesario medir, a saber, a) Dirección del flujo. b) Velocidad del flujo. c) Tasa de flujo. — printed p.13 / PDF p.14', verification_note='VA-verified 2026-09-08 (§19.1, printed p.13 / PDF p.14) [VA]', verified_at=now() where id='84a546f0-c152-494e-aa11-b8812082d321' and verification_status not in ('verified_against_standard','corrected');
-- flow_direction (ISO-5667-1-08)
update public.fields set verification_status='verified_against_standard', verification_quote='En la mayoría de los cursos de agua tierra adentro, el flujo es unidireccional y autoevidente, pero en canales navegables y en canales de drenaje esto no siempre es así y la dirección del flujo puede variar con el paso del tiempo. — printed p.13 / PDF p.14', verification_note='VA-verified 2026-09-08 (§19.2, printed p.13 / PDF p.14) [VA]', verified_at=now() where id='19577e9a-1111-489b-826a-854ac6a44d8f' and verification_status not in ('verified_against_standard','corrected');
-- flow_velocity (ISO-5667-1-08)
update public.fields set verification_status='verified_against_standard', verification_quote='La velocidad de la corriente es importante: a) Para calcular la tasa de descarga (véase el numeral 9.1). b) Para calcular la velocidad promedio o el tiempo de recorrido, que para los propósitos de la calidad del agua es el tiempo requerido para que determinada masa de agua se mueva a través de una distancia dada. — printed p.13 / PDF p.14', verification_note='VA-verified 2026-09-08 (§19.3, printed p.13 / PDF p.14) [VA]', verified_at=now() where id='cf9f723b-93ec-4b07-aba2-af03212c513f' and verification_status not in ('verified_against_standard','corrected');
-- discharge_rate (ISO-5667-1-08)
update public.fields set verification_status='verified_against_standard', verification_quote='EL caudal de descarga es el volumen de líquido que pasa por un punto dado por unidad de tiempo. La información sobre la media aritmética y los caudales extremos de descarga es esencial para el diseño y la operación del afluente, agua residual, y plantas de tratamiento de aguas, y para fijar límites de calidad racionales en cuanto a la salvaguardia de los cursos de agua naturales. — printed p.13 / PDF p.14', verification_note='VA-verified 2026-09-08 (§19.4, printed p.13 / PDF p.14) [VA]', verified_at=now() where id='b36c030f-2bb5-4697-83e2-586ffb84d0bd' and verification_status not in ('verified_against_standard','corrected');
-- flow_measurement_method (ISO-5667-1-08)
update public.fields set verification_status='verified_against_standard', verification_quote='La dirección y la velocidad se pueden medir utilizando: a) Dragas. b) Flotadores y barcos con redes rastreras. c) Trazas químicas (incluyendo tinturas). d) Trazadores microbiológicos. e) Trazadores radiactivos. | La velocidad también se puede medir utilizando: a) Medidores de la corriente, tipos de lectura directa y registro. b) Técnicas ultrasónicas. c) Técnicas electromagnéticas. d) Técnicas neumáticas. — printed p.14 / PDF p.15', verification_note='VA-verified 2026-09-08 (§21.2, §21.3, printed p.14 / PDF p.15) [VA]', verified_at=now() where id='6219d1a8-5c31-4630-9837-404a825126e5' and verification_status not in ('verified_against_standard','corrected');
-- flow_measurement_mode (ISO-5667-1-08)
update public.fields set verification_status='verified_against_standard', verification_quote='Las mediciones pueden ser discretas, tales como las que se hacen utilizando flotadores en un estuario o un medidor de lectura directa de la corriente en un río, o pueden ser continuas, tales como las que se hacen mediante la mayoría de los medidores del flujo de descarga. — printed p.14 / PDF p.15', verification_note='VA-verified 2026-09-08 (§21.1, printed p.14 / PDF p.15) [VA]', verified_at=now() where id='7740ebba-6f5f-469d-b8be-f6023f8bf915' and verification_status not in ('verified_against_standard','corrected');

-- ===== equations =====
-- Eq.1 s = sqrt( SUM((x_i - x_mean)^2) / (n - 1) )
update public.equations set verification_status='verified_against_standard', verification_quote='Para cierto número de resultados n, tomados al azar, las estimaciones de la media aritmética verdadera X y la desviación estándar, σ, son la media aritmética, X , y s respectivamente de acuerdo con la siguiente fórmula | Donde xi representa los valores individuales. — printed p.11 / PDF p.12', verification_note='VA-verified 2026-09-08 (§16.4, printed p.11 / PDF p.12) [VA]; displayed formula radical/Sigma glyphs are Symbol-font and are dropped by pdftotext — the formula was read from the rendered page image, not the text layer', verified_at=now() where id='d42f576c-c3c7-4e00-bf34-e2da20bf3886' and verification_status <> 'verified_against_standard';
-- Eq.2 L = 2 * K * sigma / sqrt(n)
update public.equations set verification_status='verified_against_standard', verification_quote='Por ejemplo, si se aplica la distribución normal, de acuerdo con lo anterior, el intervalo de confianza L de la media aritmética de n resultados, a un nivel de confianza seleccionado, está dado por la fórmula | Donde σ es la desviación estándar de la distribución. — printed p.12 / PDF p.13', verification_note='VA-verified 2026-09-08 (§16.5, printed p.12 / PDF p.13) [VA]; displayed formula radical/Sigma glyphs are Symbol-font and are dropped by pdftotext — the formula was read from the rendered page image, not the text layer', verified_at=now() where id='db88161d-3cc3-4541-92bd-4271eba4b0fc' and verification_status <> 'verified_against_standard';
-- Eq.3 n = (2 * K * sigma / L)^2
update public.equations set verification_status='verified_against_standard', verification_quote='Para estimar la media aritmética X para un intervalo de confianza dado L en el nivel de confianza seleccionado, el número de muestras necesarias es (2Kσ/L)2. Esto es estrictamente cierto únicamente cuando se conoce σ. — printed p.12 / PDF p.13', verification_note='VA-verified 2026-09-08 (§16.4, printed p.12 / PDF p.13) [VA]; displayed formula radical/Sigma glyphs are Symbol-font and are dropped by pdftotext — the formula was read from the rendered page image, not the text layer', verified_at=now() where id='8b5fc076-c947-447c-aa37-7ebbc3a3a81d' and verification_status <> 'verified_against_standard';
